// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    Recorder r;

    function setUp() public { 
        c = new EBU();
        r = new Recorder();
    }

    // fuzz the 'from' address and one value; also fuzz number of recipients via an array length
    function testFuzz_property(address from, uint256 v0, address to0, address to1, bool useTwo) public {
        // Keep inputs wide but avoid zero-length recipients: require at least one recipient
        // We'll build the _tos array with either 1 or 2 recipients based on fuzzed bool
        address[] memory tos = new address[](useTwo ? 2 : 1);
        tos[0] = to0;
        if (useTwo) tos[1] = to1;
        uint[] memory vals = new uint[](tos.length);
        // fill with v0 for all
        for (uint i = 0; i < vals.length; i++) vals[i] = v0;

        // Call c.transfer supplying the recorder's address as the caddress so we can observe
        // what selector and args C encodes in its low-level calls.
        // No ether is needed.
        bool ok;
        try c.transfer(from, address(r), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The GENERAL RULE: The reference implementation always invokes the callee function
        // with selector bytes4(keccak256("transferFrom(address,address,uint256)")) for each entry.
        // The Recorder accumulates observed selectors and decoded arguments.
        // We assert that if the call succeeded (didn't revert), then the Recorder recorded
        // exactly tos.length calls and that every recorded selector equals the
        // transferFrom selector and the decoded first/second/third args match (from, tos[i], vals[i]).
        // The mutant that uses selector transfer(...) will cause the Recorder to observe a different selector
        // (and the Recorder's explicit transferFrom handler won't be invoked), so this assertion will fail
        // for some fuzz inputs (the fuzzer will find them).

        // If the external low-level calls reverted, ok==false and the reference still satisfies
        // that no transferFrom calls were observed (recorder count == 0). We assert the property accordingly.

        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));

        if (ok) {
            // call succeeded: recorder should have recorded exactly tos.length entries with expected selector
            assertTrue(r.count() == tos.length);
            for (uint i = 0; i < uint(tos.length); i++) {
                // each recorded entry must match expected selector and arguments
                (bytes4 sel, address a0, address a1, uint256 a2) = r.get(i);
                assertTrue(sel == expected);
                assertTrue(a0 == from);
                assertTrue(a1 == tos[i]);
                assertTrue(a2 == vals[i]);
            }
        } else {
            // call reverted: reference still guarantees no successful external calls were recorded
            assertTrue(r.count() == 0);
        }
    }
}

// Recorder contract that implements the exact signature that C (reference) calls via selector
// and records each invocation. If mutant uses a different selector, these functions won't be invoked
// and Recorder will show a different observed behavior.
contract Recorder {
    struct Rec { bytes4 sel; address a0; address a1; uint256 a2; }
    Rec[] public recs;

    // Provide a function matching transferFrom(address,address,uint256)
    // so that when C encodes that selector, this function is invoked and records the args.
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        recs.push(Rec({sel: bytes4(keccak256("transferFrom(address,address,uint256)")), a0: from, a1: to, a2: v}));
        return true;
    }

    // Also provide transfer(address,address,uint256) to record if mutant calls that instead.
    function transfer(address from, address to, uint256 v) external returns (bool) {
        recs.push(Rec({sel: bytes4(keccak256("transfer(address,address,uint256)")), a0: from, a1: to, a2: v}));
        return true;
    }

    // helpers for the test to read the recorded data
    function count() external view returns (uint) { return recs.length; }
    function get(uint i) external view returns (bytes4, address, address, uint256) {
        Rec storage r = recs[i];
        return (r.sel, r.a0, r.a1, r.a2);
    }
}
